-- Run this in your Supabase SQL editor (https://supabase.com/dashboard/project/qukziojymwlvmrzapgyo/sql)

-- Step 1: Create the table
create table if not exists public.literary_bible (
  id         bigserial primary key,
  book       text        not null,
  chapter    integer     not null,
  verse      integer     not null,
  device     text        not null,
  words      text,
  sources    text,
  urls       text,
  created_at timestamptz default now()
);

create index if not exists idx_lb_book   on public.literary_bible (book);
create index if not exists idx_lb_device on public.literary_bible (device);
create index if not exists idx_lb_ref    on public.literary_bible (book, chapter, verse);

alter table public.literary_bible enable row level security;

create policy "Public read"
  on public.literary_bible for select using (true);

